import socket
import struct
import hashlib
from Crypto.Cipher import AES
from flask import Flask, request, jsonify
import os
import requests

app = Flask(__name__)

# IoT Device Message Handler
# Handles encrypted telemetry from field devices using AES-CBC

BLOCK_SIZE = 16
DEVICE_REGISTRY_URL = os.environ.get('DEVICE_REGISTRY_URL', 'http://169.254.169.254/latest/meta-data/iam/security-credentials/iot-role')

def get_device_key(device_id):
    """Fetch device-specific encryption key from registry/metadata"""
    try:
        resp = requests.get(f"{DEVICE_REGISTRY_URL}/{device_id}", timeout=2)
        if resp.status_code == 200:
            key_material = resp.json().get('key', '')
            return hashlib.sha256(key_material.encode()).digest()[:16]
    except Exception:
        pass
    # Fallback to derived key
    return hashlib.sha256(f"iot-device-{device_id}-v2".encode()).digest()[:16]

def pkcs7_unpad(data):
    """Remove PKCS7 padding - returns unpadded data or raises ValueError"""
    if len(data) == 0:
        raise ValueError("Empty data")
    pad_byte = data[-1]
    if pad_byte < 1 or pad_byte > BLOCK_SIZE:
        raise ValueError("Invalid padding byte")
    for i in range(pad_byte):
        if data[-(i+1)] != pad_byte:
            raise ValueError("Invalid padding")
    return data[:-pad_byte]

def decrypt_message(ciphertext, key):
    """Decrypt AES-CBC message with IV prepended"""
    if len(ciphertext) < BLOCK_SIZE * 2:
        raise ValueError("Message too short")
    if len(ciphertext) % BLOCK_SIZE != 0:
        raise ValueError("Invalid ciphertext length")
    iv = ciphertext[:BLOCK_SIZE]
    ct = ciphertext[BLOCK_SIZE:]
    cipher = AES.new(key, AES.MODE_CBC, iv)
    plaintext = cipher.decrypt(ct)
    return pkcs7_unpad(plaintext)

@app.route('/api/v1/telemetry', methods=['POST'])
def receive_telemetry():
    """Receive encrypted telemetry from IoT devices"""
    device_id = request.headers.get('X-Device-ID', 'unknown')
    if not request.data:
        return jsonify({'status': 'error', 'message': 'No data'}), 400

    key = get_device_key(device_id)
    ciphertext = request.data

    try:
        plaintext = decrypt_message(ciphertext, key)
        # Process telemetry
        return jsonify({
            'status': 'ok',
            'bytes_received': len(plaintext),
            'device': device_id
        }), 200
    except ValueError as e:
        # VULNERABILITY: Different error responses for padding vs other errors
        error_msg = str(e)
        if 'padding' in error_msg.lower():
            return jsonify({
                'status': 'error',
                'code': 'DECRYPT_PAD_ERROR',
                'message': 'Decryption failed: padding validation error'
            }), 400
        else:
            return jsonify({
                'status': 'error', 
                'code': 'DECRYPT_FORMAT_ERROR',
                'message': f'Decryption failed: {error_msg}'
            }), 400
    except Exception as e:
        return jsonify({
            'status': 'error',
            'code': 'INTERNAL_ERROR',
            'message': 'Processing failed'
        }), 500

@app.route('/api/v1/device/register', methods=['POST'])
def register_device():
    """Register new IoT device - fetches credentials from metadata"""
    data = request.get_json()
    device_id = data.get('device_id')
    try:
        creds = requests.get(DEVICE_REGISTRY_URL, timeout=2)
        return jsonify({'status': 'registered', 'device': device_id}), 201
    except requests.exceptions.ConnectionError:
        return jsonify({'status': 'registered', 'device': device_id, 'mode': 'offline'}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'}), 200

